+        throw new PitSnapshotConflictError(pitKey, frozen.provenance.asOf);
+      }
+
+      this.db
+        .prepare(
+          `INSERT INTO pit_market_data_snapshots
+             (snapshot_digest, pit_key, company_id, domain, security_id, as_of, as_of_ms, envelope_json, ingested_at)
