+    const rows = this.db
+      .prepare(
+        `SELECT snapshot_digest, pit_key, envelope_json FROM pit_market_data_snapshots
+          WHERE pit_key = ? AND as_of_ms >= ? AND as_of_ms <= ?
+          ORDER BY as_of_ms ASC`,
+      )
+      .all(key, fromMs, toMs) as unknown as SnapshotRow[];
