+  /** Removes every snapshot. Retained for parity with the in-memory store. */
+  public clear(): void {
+    this.assertOpen();
+    this.db.exec('BEGIN IMMEDIATE;');
+    try {
+      this.db.exec('DELETE FROM pit_market_data_snapshots;');
+      this.db.exec('COMMIT;');
+    } catch (error) {
+      this.db.exec('ROLLBACK;');
+      throw error;
+    }
+  }
+
+  public close(): void {
+    if (!this.closed) {
+      this.db.close();
+      this.closed = true;
+    }
+  }
+}

